head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



// 포커스된 Cell 이 있어야 syncRowPositionOption 이 동작하므로 사전에 (0,0) 을 지정한다.
//  또한 방향키 입력이 어디로 들어가는지 눈으로 확인할 수 있도록 키 입력을 감시한다.
scwin.onpageload = function () {
    target1.setFocusedCell(0, 0);
    dlt_bind.setRowPosition(0);

    document.addEventListener("keydown", function (objEvent) {
        if (objEvent.key !== "ArrowDown") { return; }
        var strBefore = scwin.focusedCellText();
        setTimeout(function () {
            var strAfter = scwin.focusedCellText();
            scwin.setReturnValue("[아래 방향키 입력] 주황색 Cell : " + strBefore + " -> " + strAfter
                + (strBefore === strAfter ? "  (변화 없음)" : "  (아래 Row 로 이동함)"));
        }, 200);
    }, true);
};



// 현재 포커스 표시(주황색)가 있는 Cell 의 값을 돌려준다.
scwin.focusedCellText = function () {
    var objCell = target1.render.querySelector(".focusedTd");
    return (objCell === null) ? "없음" : objCell.textContent.trim();
};



// 현재 실제 포커스(activeElement) 를 "태그#id" 로 표현한다.
scwin.activeText = function () {
    var objActive = document.activeElement;
    if (objActive === null) { return "없음"; }
    return objActive.tagName + (objActive.id === "" ? "" : "#" + objActive.id);
};



// 대상 Cell 에 포커스 표시 스타일(focusedTd) 이 적용되었는지 확인한다.
//  이 표시는 논리 포커스 동기화의 결과로, 정상 동작에 해당한다.
scwin.cellFocusText = function (nRowIndex) {
    var objCell = document.getElementById(target1.id + "_cell_" + nRowIndex + "_0");
    if (objCell === null) { return "Cell 없음"; }
    var bFocused = (objCell.className.indexOf("focusedTd") >= 0);
    return (bFocused ? "적용됨" : "없음") + " (배경 " + window.getComputedStyle(objCell).backgroundColor + ")";
};



scwin.btn_setRowPosition_onclick = function (e) {
    var strBefore = scwin.activeText();
    var nBeforeRow = target1.getFocusedRowIndex();

    // 바인딩된 DataList 의 rowPosition 을 2 로 변경한다.
    dlt_bind.setRowPosition(2);

    var strAfter = scwin.activeText();
    var nAfterRow = target1.getFocusedRowIndex();

    scwin.setReturnValue("=====dlt_bind.setRowPosition(2) 실행=====");
    scwin.setReturnValue("    논리 포커스(getFocusedRowIndex) : " + nBeforeRow + " -> " + nAfterRow);
    scwin.setReturnValue("    2번 Row Cell 의 포커스 표시 : " + scwin.cellFocusText(2));
    scwin.setReturnValue("    실제 포커스(activeElement) : " + strBefore + " -> " + strAfter);
    scwin.setReturnValue("");

    scwin.setReturnValue("----- 판정 -----");
    if (strBefore === strAfter) {
        scwin.setReturnValue("논리 포커스만 동기화되고 실제 포커스는 이동하지 않는다");
    } else {
        scwin.setReturnValue("논리 포커스뿐 아니라 실제 포커스까지 GridView 의 Cell 로 이동했다");
    }
    scwin.setReturnValue("(Cell 이 주황색으로 표시되는 것은 논리 포커스 동기화의 결과로 정상이다)");
    scwin.setReturnValue("");
    scwin.setReturnValue(">> 이제 마우스를 건드리지 말고 아래 방향키를 한 번 누르세요. 주황색 Cell 이 아래로 내려가는지 보세요.");
    scwin.setReturnValue("");
};
